import React, {useEffect} from 'react'
import {announceFromElement} from '@github-ui/aria-live'

import {Spinner} from '@primer/react'
import type {BetterSystemStyleObject} from '@primer/styled-react'
import {Box} from '@primer/styled-react'
import {Octicon} from '@primer/react/deprecated'
import {CheckIcon, AlertIcon} from '@primer/octicons-react'

import styles from './State.module.css'

export const Sections = {
  Notifications: 'notifications',
  Watching: 'watching',
  System: 'system',
} as const

export type Sections = (typeof Sections)[keyof typeof Sections]

export const SavingStatus = {
  IDLE: '',
  LOADING: 'loading',
  SUCCESS: 'success',
  ERROR: 'error',
} as const

export type SavingStatus = (typeof SavingStatus)[keyof typeof SavingStatus]

interface StateProps {
  sx?: BetterSystemStyleObject
  status: SavingStatus
  className?: string
}

function State(props: StateProps) {
  const {status} = props
  const ref = React.useRef<HTMLDivElement>(null)
  const [isDisplayed, setDisplayed] = React.useState(status !== SavingStatus.IDLE)

  const successStatus = () => {
    return (
      <>
        <Octicon icon={CheckIcon} size={12} className={styles.successIcon} />
        <span className={styles.savedText}>Saved</span>
      </>
    )
  }

  const succeeded = status === SavingStatus.SUCCESS

  useEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout> | null

    if (succeeded) {
      timeoutId = setTimeout(() => setDisplayed(false), 3000)
    } else {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setDisplayed(true)
    }

    return () => {
      if (timeoutId) {
        clearTimeout(timeoutId)
      }
    }
  }, [succeeded])

  const renderStatus = () => {
    return status === SavingStatus.SUCCESS ? successStatus() : <span className={styles.statusText}>{status}</span>
  }

  useEffect(() => {
    if (ref.current) {
      announceFromElement(ref.current, {assertive: status === SavingStatus.ERROR})
    }
  }, [status, ref])

  if (!isDisplayed) return null

  return (
    <Box sx={{...props.sx}} ref={ref} className={props.className}>
      {status === SavingStatus.ERROR ? (
        <span className={styles.errorText}>
          <Octicon icon={AlertIcon} size={12} className={styles.errorIcon} />
          Oops, something went wrong.
        </span>
      ) : (
        <>{status === SavingStatus.LOADING ? <Spinner size="small" /> : renderStatus()}</>
      )}
    </Box>
  )
}

export default State

try{ State.displayName ||= 'State' } catch {}